function [facecenterslab,facenormalslab] = SurfPtCoords(samplefacecenters,samplefacenormals,r_sam2lab)%% called by ComputeForceMatrics%% compute qp coordinates in sample CRD using mesh coordinates (in sample CRD)facecenterslab = zeros(6,3);facenormalslab = zeros(6,3);for i=1:1:6     facecenterslab(i,:) = r_sam2lab(:,:)*samplefacecenters(i,:)';       facenormalslab(i,:) = r_sam2lab(:,:)*samplefacenormals(i,:)'; endend 